            if abs(a.y-b.y)<0.5 and abs(a.x-b.x)>150:
                hs.append((round(a.y,1),round(min(a.x,b.x),1),round(max(a.x,b.x),1)))
print('vertical x',sorted(set(v[0] for v in vs)))
print('horizontal y',sorted(set(h[0] for h in hs)))
